            '../../common/smAsync.js': smAsyncMod,
            '../../common/mutexRegistry.js': loadModule('js/common/mutexRegistry.js', makeRequire({}), {}),
            '../../common/guestTransplant.js': loadModule('js/common/guestTransplant.js', makeRequire({
