                publish();
                var items = source.query({
                    limit: 1,
                    query: { type: 'pr', labels: ['pr_approved'],
                        notLabels: ['ai_validating', 'validation_failed'],
                        notMergeState: ['BEHIND', 'DIRTY'], draft: false,
