// Structural constructs pay basic + nesting and deepen their subtree;
// IfStatement gets its own dispatch (flat else-if chains, else increments).
function structuralStep(s, n, depth, visit) {
  s.score += 1 + depth;
  if (n.type === 'IfStatement') {
