        { prefix: 'git rev-list --count', run: function () { return '2'; } },
        { prefix: 'git fetch', run: function () { return ''; } },
        { prefix: 'git rev-parse origin/', run: function () { return 'basesha123'; } },
        { prefix: 'git merge-base', run: function () { return 'basesha123'; } },
